def handler(params):
    import json
    import os
    import urllib.request

    query = (params.get('query') or '').strip()
    if not query:
        return {'error': 'query is required'}

    max_results = params.get('max_results', params.get('limit', 5))
    try:
        max_results = int(max_results)
    except Exception:
        max_results = 5
    max_results = min(max(1, max_results), 20)

    api_key = os.environ.get('TAVILY_API_KEY', '').strip()
    if not api_key:
        return {
            'query': query,
            'results': [],
            'note': 'TAVILY_API_KEY is not loaded in the backend process. Add it to backend/.env and restart the backend.'
        }

    payload = json.dumps({
        'api_key': api_key,
        'query': query,
        'max_results': max_results,
        'search_depth': 'basic',
        'include_answer': False,
        'include_raw_content': False,
    }).encode('utf-8')

    req = urllib.request.Request(
        'https://api.tavily.com/search',
        data=payload,
        headers={'Content-Type': 'application/json'},
        method='POST',
    )

    try:
        with urllib.request.urlopen(req, timeout=20) as resp:
            data = json.loads(resp.read().decode('utf-8'))
    except Exception as exc:
        return {'query': query, 'results': [], 'note': 'Search failed: %s' % exc}

    results = []
    for item in data.get('results', []):
        results.append({
            'title': item.get('title', ''),
            'snippet': item.get('content', ''),
            'url': item.get('url', ''),
        })

    if not results:
        return {'query': query, 'results': [], 'note': 'No results found.'}
    return {'query': query, 'results': results}

def handler(params):
    import ast
    expr = params.get('expression', '')
    result = eval(compile(ast.parse(expr, mode='eval'), '<expr>', 'eval'))
    return {'result': str(result)}

def handler(params):
    from datetime import datetime, timezone
    tz = params.get('timezone', 'UTC')
    now = datetime.now(timezone.utc)
    return {'datetime': now.isoformat(), 'timezone': tz}
